import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/context/AuthContext";
import api from "@/utils/api";
import toast from "react-hot-toast";
import { Eye, EyeOff } from "lucide-react";

import logoLight from "@/assets/logo-cdotchad.png";
import logoDark from "@/assets/logo-cdo-dark.png";

export default function AdminLogin() {
  const navigate = useNavigate();
  const { login } = useAuth();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [rememberMe, setRememberMe] = useState(true);
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  // 🔁 Redirection automatique si déjà connecté
  useEffect(() => {
    const stored = localStorage.getItem("adminUser") || sessionStorage.getItem("adminUser");
    try {
      const user = stored ? JSON.parse(stored) : null;
      if (user) navigate("/admin/dashboard");
    } catch {
      localStorage.removeItem("adminUser");
      sessionStorage.removeItem("adminUser");
    }
  }, [navigate]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await api.post("/admin/login", {
        email,
        motdepasse: password,
      });

      if (res.data?.token && res.data?.admin) {
        login(res.data.token, res.data.admin, rememberMe);

        // 🕒 Attente de propagation du token dans le contexte + localStorage
        await new Promise((resolve) => setTimeout(resolve, 500));

        toast.success("Connexion réussie !");
        navigate("/admin/dashboard");
      } else {
        toast.error("Réponse invalide du serveur");
      }
    } catch (err) {
      toast.error("Identifiants incorrects");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 dark:bg-gray-900">
      <form
        onSubmit={handleSubmit}
        className="bg-white dark:bg-gray-800 p-8 rounded shadow-md w-full max-w-md space-y-4"
      >
        <div className="flex justify-center mb-2">
          <img src={logoLight} alt="Logo CDO" className="h-16 block dark:hidden" />
          <img src={logoDark} alt="Logo CDO (dark)" className="h-16 hidden dark:block" />
        </div>

        <h2 className="text-2xl font-bold text-center text-red-600 dark:text-white">
          Connexion Admin
        </h2>

        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="w-full p-2 border rounded dark:bg-gray-700 dark:text-white"
          required
        />

        <div className="relative">
          <input
            type={showPassword ? "text" : "password"}
            placeholder="Mot de passe"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full p-2 border rounded dark:bg-gray-700 dark:text-white pr-10"
            required
          />
          <button
            type="button"
            onClick={() => setShowPassword(!showPassword)}
            className="absolute right-2 top-1/2 transform -translate-y-1/2 text-gray-500 dark:text-gray-300"
            tabIndex={-1}
          >
            {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
          </button>
        </div>

        <label className="flex items-center space-x-2 text-sm dark:text-white">
          <input
            type="checkbox"
            checked={rememberMe}
            onChange={() => setRememberMe(!rememberMe)}
          />
          <span>Se souvenir de moi</span>
        </label>

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-red-600 hover:bg-red-700 text-white font-semibold py-2 px-4 rounded transition"
        >
          {loading ? "Connexion..." : "Se connecter"}
        </button>
      </form>
    </div>
  );
}
